22	
23	/// "Meus Registros" (data-model.md). The `ScrollController` is created once
24	/// and never recreated across `BlocBuilder` rebuilds, which is what
25	/// preserves scroll position across state changes (FR-003/FR-007).
26	class RecordsPage extends StatefulWidget {
27	  const RecordsPage({super.key});
28	
29	  @override
30	  State<RecordsPage> createState() => _RecordsPageState();
31	}
32	
33	class _RecordsPageState extends State<RecordsPage> {
34	  final _scrollController = ScrollController();
35	  late final StreamSubscription<void> _reauthSubscription;
36	
37	  @override
38	  void initState() {
39	    super.initState();
40	    // `RecordsStarted` is dispatched once by the route builder itself
41	    // (`AppRoutes.records`, app_router.dart) right after `RecordsBloc` is
42	    // constructed — not here, to avoid double-fetching the first page.
43	    _scrollController.addListener(_maybeRequestNextPage);
44	    // The one sanctioned cross-bloc touch point (research.md R5) — lives in
45	    // this widget, never inside `RecordsBloc` itself.
46	    _reauthSubscription = context.read<RecordsBloc>().reauthRequired.listen((_) {
47	      if (!mounted) return;
48	      context.read<SessionBloc>().add(const AuthExpiredDetected());
49	    });
50	  }
51	
52	  void _maybeRequestNextPage() {
53	    if (!_scrollController.hasClients) return;
54	    final position = _scrollController.position;
55	    if (position.pixels >= position.maxScrollExtent - 200) {
56	      context.read<RecordsBloc>().add(const NextPageRequested());
57	    }
58	  }
59	
60	  @override
61	  void dispose() {
62	    _scrollController.dispose();
63	    _reauthSubscription.cancel();
64	    super.dispose();
65	  }
66	
67	  @override
68	  Widget build(BuildContext context) {
69	    return Scaffold(
70	      backgroundColor: DesignTokens.colorSurfaceBg,
71	      body: SafeArea(
72	        child: Column(
73	          children: [
74	            _Header(),
75	            _SearchBar(),
76	            BlocBuilder<RecordsBloc, RecordsState>(
77	              builder: (context, state) {
78	                final isOffline = state is RecordsLoaded &&
79	                    (state.pageLoadFailure is NetworkOfflineFailure ||
80	                        state.criteriaLoadFailure is NetworkOfflineFailure);
81	                if (!isOffline) return const SizedBox.shrink();
82	                return Padding(
83	                  padding: const EdgeInsets.fromLTRB(
84	                    DesignTokens.spacingMd,
85	                    0,
86	                    DesignTokens.spacingMd,
87	                    DesignTokens.spacingSm,
88	                  ),
89	                  child: Align(
90	                    alignment: Alignment.centerLeft,
91	                    child: Text(
92	                      'Busca limitada ao que está salvo no aparelho.',
93	                      style: DesignTokens.textBodyMd.copyWith(
94	                        color: DesignTokens.colorInfoOffline,
95	                      ),
96	                    ),
97	                  ),
98	                );
99	              },
100	            ),
101	            BlocBuilder<RecordsBloc, RecordsState>(
102	              builder: (context, state) {
103	                if (state is! RecordsLoaded || state.activeChips.isEmpty) {
104	                  return const SizedBox.shrink();
105	                }
106	                return Padding(
107	                  padding: const EdgeInsets.fromLTRB(
108	                    DesignTokens.spacingMd,
109	                    0,
110	                    DesignTokens.spacingMd,
111	                    DesignTokens.spacingMd,
112	                  ),
113	                  child: ActiveFilterChipsRow(chips: state.activeChips),
114	                );
115	              },
116	            ),
117	            Expanded(
118	              child: BlocBuilder<RecordsBloc, RecordsState>(
119	                builder: (context, state) => switch (state) {
120	                  RecordsLoading() => const Center(child: CircularProgressIndicator()),
121	                  RecordsLoadFailure(:final failure) => _LoadFailureView(message: failure.message),
122	                  RecordsLoaded() => _buildLoaded(context, state),
123	                },
124	              ),
125	            ),
126	          ],
127	        ),
128	      ),
129	    );
130	  }
131	
132	  Future<void> _openEmptyStateCreate(BuildContext context) async {
133	    await openInsertionModal(context);
134	    if (context.mounted) {
135	      context.read<RecordsBloc>().add(const RecordsLocalCacheRefreshed());
136	    }
137	  }
138	
139	  Widget _buildLoaded(BuildContext context, RecordsLoaded loaded) {
140	    if (loaded.isEmptyForCriteria) {
141	      return NoResultsForCriteriaView(
142	        onAdjustPressed: () =>
143	            context.read<RecordsBloc>().add(const FiltersAndSearchCleared()),
144	      );
145	    }
146	    if (loaded.isEmpty) {
147	      return RecordsEmptyState(onCreatePressed: () => _openEmptyStateCreate(context));
148	    }
149	
150	    final groups = DateGrouper.group(loaded.entries);
151	
152	    return CustomScrollView(
153	      controller: _scrollController,
154	      slivers: [
155	        if (loaded.isApplyingCriteria)
156	          const SliverPadding(
157	            padding: EdgeInsets.all(DesignTokens.spacingMd),
158	            sliver: SliverToBoxAdapter(child: Center(child: CircularProgressIndicator())),
159	          ),
160	        if (loaded.criteriaLoadFailure != null)
161	          SliverPadding(
162	            padding: const EdgeInsets.all(DesignTokens.spacingMd),
163	            sliver: SliverToBoxAdapter(
164	              child: _RetryBanner(
165	                message: loaded.criteriaLoadFailure!.message,
166	                onRetry: () => context.read<RecordsBloc>().add(const CriteriaLoadRetried()),
167	              ),
168	            ),
169	          ),
170	        for (final group in groups) _dateGroupSliver(group),
171	        if (loaded.isLoadingMore)
172	          const SliverPadding(
173	            padding: EdgeInsets.all(DesignTokens.spacingMd),
174	            sliver: SliverToBoxAdapter(child: Center(child: CircularProgressIndicator())),
175	          ),
176	        if (loaded.pageLoadFailure != null)
177	          SliverPadding(
178	            padding: const EdgeInsets.all(DesignTokens.spacingMd),
179	            sliver: SliverToBoxAdapter(
180	              child: _RetryBanner(
181	                message: loaded.pageLoadFailure!.message,
182	                onRetry: () => context.read<RecordsBloc>().add(const PageLoadRetried()),
183	              ),
184	            ),
185	          ),
186	      ],
187	    );
188	  }
189	
190	  // Each group's date heading pins to the top only while its own entries
191	  // scroll underneath it, then gives way to the next group's heading —
192	  // `SliverMainAxisGroup` scopes the pinned `SliverPersistentHeader` to just
193	  // the slivers listed here, instead of the whole scroll view.
194	  Widget _dateGroupSliver(DateGroup group) {
195	    return SliverMainAxisGroup(
196	      slivers: [
197	        SliverPersistentHeader(pinned: true, delegate: _DateHeaderDelegate(label: group.label)),
198	        SliverList.list(children: [for (final entry in group.entries) RecordCard(entry: entry)]),
199	      ],
200	    );
201	  }
202	}
203	
204	class _Header extends StatelessWidget {
205	  @override
206	  Widget build(BuildContext context) {
207	    return Padding(
208	      padding: const EdgeInsets.fromLTRB(
209	        DesignTokens.spacingMd,
210	        DesignTokens.spacingMd,
211	        DesignTokens.spacingMd,
212	        DesignTokens.spacingSm,
213	      ),
214	      child: Row(
215	        children: [
216	          IconButton(
217	            onPressed: () => context.pop(),
218	            icon: const Icon(Icons.arrow_back, color: DesignTokens.colorTextPrimary),
219	          ),
220	          const Expanded(
221	            child: Text('Meus Registros', style: DesignTokens.textHeadlineMd),
222	          ),
223	          // Inert placeholder — no export behavior in this unit (FR-008).
224	          IconButton(
225	            onPressed: () {},
226	            icon: const Icon(Icons.download_outlined, color: DesignTokens.colorTextPrimary),
227	          ),
228	        ],
229	      ),
230	    );
231	  }
232	}
233	
234	class _SearchBar extends StatelessWidget {
235	  static const _pillBorder = OutlineInputBorder(
236	    borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusFull)),
237	    borderSide: BorderSide(color: DesignTokens.colorBorder),
238	  );
239	
240	  @override
241	  Widget build(BuildContext context) {
242	    final state = context.watch<RecordsBloc>().state;
243	    final dateRange = state is RecordsLoaded ? state.dateRange : DateRangeOption.allTime;
244	    final entryTypes = state is RecordsLoaded ? state.entryTypes : const <EntrySource>{};
245	    final hasActiveFilters = state is RecordsLoaded && state.hasActiveFilters;
246	
247	    return Padding(
248	      padding: const EdgeInsets.fromLTRB(
249	        DesignTokens.spacingMd,
250	        0,
251	        DesignTokens.spacingMd,
252	        DesignTokens.spacingMd,
253	      ),
254	      child: Row(
255	        children: [
256	          Expanded(
257	            child: TextField(
258	              enabled: true,
259	              onChanged: (text) =>
260	                  context.read<RecordsBloc>().add(SearchTextChanged(text)),
261	              decoration: const InputDecoration(
262	                hintText: 'Buscar nos registros...',
263	                prefixIcon: Icon(
264	                  Icons.search,
265	                  size: DesignTokens.spacingMd,
266	                  color: DesignTokens.colorTextSecondary,
267	                ),
268	                border: _pillBorder,
269	                enabledBorder: _pillBorder,
270	                disabledBorder: _pillBorder,
271	                focusedBorder: _pillBorder,
272	              ),
273	            ),
274	          ),
275	          const SizedBox(width: DesignTokens.spacingSm),
276	          IconButton(
277	            onPressed: () => _openFilterSheet(
278	              context,
279	              dateRange: dateRange,
280	              entryTypes: entryTypes,
281	            ),
282	            icon: Icon(
283	              Icons.filter_alt,
284	              color: hasActiveFilters
285	                  ? DesignTokens.colorOnAccent
286	                  : DesignTokens.colorTextPrimary,
287	            ),
288	            style: IconButton.styleFrom(
289	              backgroundColor: hasActiveFilters
290	                  ? DesignTokens.colorAccent
291	                  : DesignTokens.colorSurfaceElevated,
292	              side: const BorderSide(color: DesignTokens.colorBorder),
293	              shape: const CircleBorder(),
294	              fixedSize: const Size(40, 40),
295	            ),
296	          ),
297	        ],
298	      ),
299	    );
300	  }
301	
302	  Future<void> _openFilterSheet(
303	    BuildContext context, {
304	    required DateRangeOption dateRange,
305	    required Set<EntrySource> entryTypes,
306	  }) async {
307	    final bloc = context.read<RecordsBloc>();
308	    final result =
309	        await showModalBottomSheet<({DateRangeOption dateRange, Set<EntrySource> entryTypes})>(
310	          context: context,
311	          isScrollControlled: true,
312	          builder: (_) =>
313	              FilterSheet(initialDateRange: dateRange, initialEntryTypes: entryTypes),
314	        );
315	    if (result != null) {
316	      bloc.add(FilterSheetApplied(dateRange: result.dateRange, entryTypes: result.entryTypes));
317	    }
318	  }
319	}
320	
321	/// A date heading (e.g. "Hoje") pinned to the top of its own group only
322	/// (data-model.md — pure prototype-fidelity rendering).
323	class _DateHeaderDelegate extends SliverPersistentHeaderDelegate {
324	  const _DateHeaderDelegate({required this.label});
325	
326	  final String label;
327	
328	  static const double _extent = 32;
329	
330	  @override
331	  double get minExtent => _extent;
332	
333	  @override
334	  double get maxExtent => _extent;
335	
336	  @override
337	  Widget build(BuildContext context, double shrinkOffset, bool overlapsContent) {
338	    return Container(
339	      color: DesignTokens.colorSurfaceBg,
340	      padding: const EdgeInsets.fromLTRB(
341	        DesignTokens.spacingMd,
342	        DesignTokens.spacingSm,
343	        DesignTokens.spacingMd,
344	        DesignTokens.spacingXs,
345	      ),
346	      alignment: Alignment.centerLeft,
347	      child: Text(
348	        label,
349	        style: DesignTokens.textMonoCaption.copyWith(color: DesignTokens.colorTextSecondary),
350	      ),
351	    );
352	  }
353	
354	  @override
355	  bool shouldRebuild(covariant _DateHeaderDelegate oldDelegate) => oldDelegate.label != label;
356	}
357	
358	class _LoadFailureView extends StatelessWidget {
359	  const _LoadFailureView({required this.message});
360	
361	  final String message;
362	
363	  @override
364	  Widget build(BuildContext context) {
365	    return Center(
366	      child: Padding(
367	        padding: const EdgeInsets.all(DesignTokens.spacingLg),
368	        child: Column(
369	          mainAxisSize: MainAxisSize.min,
370	          children: [
371	            Text(message, style: DesignTokens.textBodyLg, textAlign: TextAlign.center),
372	            const SizedBox(height: DesignTokens.spacingMd),
373	            ElevatedButton(
374	              onPressed: () => context.read<RecordsBloc>().add(const PageLoadRetried()),
375	              child: const Text('Tentar novamente'),
376	            ),
377	          ],
378	        ),
379	      ),
380	    );
381	  }
382	}
383	
384	class _RetryBanner extends StatelessWidget {
385	  const _RetryBanner({required this.message, required this.onRetry});
386	
