1	import 'dart:async';
2	
3	import 'package:cerne/core/network/connectivity_checker.dart';
4	import 'package:cerne/core/network/failure.dart';
5	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
6	import 'package:cerne/features/chat/domain/entities/chat_stream_event.dart';
7	import 'package:cerne/features/chat/domain/entities/chat_title_deriver.dart';
8	import 'package:cerne/features/chat/domain/repositories/chat_repository.dart';
9	import 'package:cerne/features/chat/presentation/bloc/chat_event.dart';
10	import 'package:cerne/features/chat/presentation/bloc/chat_state.dart';
11	import 'package:flutter_bloc/flutter_bloc.dart';
12	import 'package:fpdart/fpdart.dart';
13	
14	/// The Home/Chat screen's own live conversation — streaming, retry, lazy
15	/// session creation, composer gating (contracts/chat-bloc.md). Depends only
16	/// on `ChatRepository` + `ConnectivityChecker` — never `ChatSessionsBloc`
17	/// nor `SessionBloc` (research.md R7).
18	class ChatBloc extends Bloc<ChatEvent, ChatState> {
19	  ChatBloc({
20	    required ChatRepository chatRepository,
21	    required ConnectivityChecker connectivityChecker,
22	  }) : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
23	       _connectivityChecker = connectivityChecker, // ignore: prefer_initializing_formals
24	       super(const ChatLoading()) {
25	    on<ChatStarted>(_onStarted);
26	    on<ConversationSelected>(_onConversationSelected);
27	    on<NewConversationRequested>(_onNewConversationRequested);
28	    on<MessageSubmitted>(_onMessageSubmitted);
29	    on<MessageRetryRequested>(_onMessageRetryRequested);
30	    on<ChatConnectivityChanged>(_onConnectivityChanged);
31	    _connectivitySubscription = connectivityChecker.onConnectivityChanged.listen(
32	      (isOnline) => add(ChatConnectivityChanged(isOnline)),
33	    );
34	  }
35	
36	  final ChatRepository _chatRepository;
37	  final ConnectivityChecker _connectivityChecker;
38	  late final StreamSubscription<bool> _connectivitySubscription;
39	  final _reauthController = StreamController<void>.broadcast();
40	
41	  /// Guards against a resolved/superseded turn's late emit (defensive,
42	  /// research.md R9) — bumped on every new turn and on every conversation
43	  /// switch/new-conversation request.
44	  int _turnGeneration = 0;
45	
46	  /// A one-shot side effect, not a state (research.md R3/R7) —
47	  /// `HomeChatShellPage` listens to this to raise the "Sessão expirada"
48	  /// overlay.
49	  Stream<void> get reauthRequired => _reauthController.stream;
50	
51	  Future<void> _onStarted(ChatStarted event, Emitter<ChatState> emit) async {
52	    final isOnline = await _connectivityChecker.hasConnection();
53	    final lastId = await _chatRepository.lastActiveSessionId;
54	    if (lastId == null) {
55	      emit(
56	        ChatReady(
57	          sessionId: null,
58	          messages: const [],
59	          isOffline: !isOnline,
60	          awaitingResponse: false,
61	        ),
62	      );
63	      return;
64	    }
65	    await _loadSession(lastId, emit, isOffline: !isOnline);
66	  }
67	
68	  Future<void> _onConversationSelected(
69	    ConversationSelected event,
70	    Emitter<ChatState> emit,
71	  ) async {
72	    _turnGeneration++;
73	    final isOnline = await _connectivityChecker.hasConnection();
74	    await _loadSession(event.sessionId, emit, isOffline: !isOnline);
75	  }
76	
77	  Future<void> _onNewConversationRequested(
78	    NewConversationRequested event,
79	    Emitter<ChatState> emit,
80	  ) async {
81	    _turnGeneration++;
82	    final current = state;
83	    final isOffline = current is ChatReady ? current.isOffline : false;
84	    await _chatRepository.setLastActiveSessionId(null);
85	    emit(
86	      ChatReady(
87	        sessionId: null,
88	        messages: const [],
89	        isOffline: isOffline,
90	        awaitingResponse: false,
91	      ),
92	    );
93	  }
94	
95	  void _onConnectivityChanged(
96	    ChatConnectivityChanged event,
97	    Emitter<ChatState> emit,
98	  ) {
99	    final current = state;
100	    if (current is! ChatReady) return;
101	    emit(current.copyWith(isOffline: !event.isOnline));
102	  }
103	
104	  /// The shared fetch-with-cache-fallback path (Clarification 3).
105	  Future<void> _loadSession(
106	    String sessionId,
107	    Emitter<ChatState> emit, {
108	    required bool isOffline,
109	  }) async {
110	    final result = await _chatRepository.listMessages(sessionId);
111	    await result.match(
112	      (failure) async {
113	        if (failure is AuthExpiredFailure) _reauthController.add(null);
114	        final cached = _chatRepository.cachedMessages(sessionId);
115	        if (cached == null) {
116	          // Never opened while online — the "standard no-connection state"
117	          // instead of any content (Edge Cases).
118	          emit(
119	            ChatReady(
120	              sessionId: sessionId,
121	              messages: const [],
122	              isOffline: isOffline,
123	              awaitingResponse: false,
124	              loadFailure: failure,
125	            ),
126	          );
127	        } else {
128	          emit(
129	            ChatReady(
130	              sessionId: sessionId,
131	              messages: cached,
132	              isOffline: isOffline,
133	              awaitingResponse: false,
134	            ),
135	          );
136	        }
137	      },
138	      (messages) async {
139	        await _chatRepository.setLastActiveSessionId(sessionId);
140	        emit(
141	          ChatReady(
142	            sessionId: sessionId,
143	            messages: messages,
144	            isOffline: isOffline,
145	            awaitingResponse: false,
146	          ),
147	        );
148	      },
149	    );
150	  }
151	
152	  Future<void> _onMessageSubmitted(
153	    MessageSubmitted event,
154	    Emitter<ChatState> emit,
155	  ) async {
156	    final current = state;
157	    if (current is! ChatReady || !current.canSend) return;
158	
159	    if (!await _connectivityChecker.hasConnection()) {
160	      // FR-012 — blocked client-side, never attempted. The composer's own
161	      // isOffline flag (R8's live stream) reflects this on its own shortly.
162	      return;
163	    }
164	
165	    final generation = ++_turnGeneration;
166	    final now = DateTime.now();
167	    final optimisticUser = ChatMessage(
168	      id: 'local-${now.microsecondsSinceEpoch}',
169	      sessionId: current.sessionId ?? '',
170	      role: ChatRole.user,
171	      content: event.text,
172	      seq: current.messages.length,
173	      status: ChatMessageStatus.complete,
174	      retryCount: 0,
175	      createdAt: now,
176	    );
177	    final optimisticAssistant = ChatMessage(
178	      id: 'local-${now.microsecondsSinceEpoch}-response',
179	      sessionId: current.sessionId ?? '',
180	      role: ChatRole.assistant,
181	      content: '',
182	      seq: current.messages.length + 1,
183	      status: ChatMessageStatus.streaming,
184	      retryCount: 0,
185	      createdAt: now,
186	    );
187	    emit(
188	      current.copyWith(
189	        messages: [...current.messages, optimisticUser, optimisticAssistant],
190	        awaitingResponse: true,
191	      ),
192	    );
193	
194	    String sessionId;
195	    if (current.sessionId == null) {
196	      final created = await _chatRepository.createSession(
197	        title: ChatTitleDeriver.derive(event.text),
198	      );
199	      if (generation != _turnGeneration) return;
200	      final maybeId = created.match((_) => null, (s) => s.id);
201	      if (maybeId == null) {
202	        final failure = created.getLeft().toNullable()!;
203	        _failTurn(emit, optimisticAssistant.id, failure);
204	        return;
205	      }
206	      sessionId = maybeId;
207	      await _chatRepository.setLastActiveSessionId(sessionId);
208	    } else {
209	      sessionId = current.sessionId!;
210	    }
211	
212	    final stream = _chatRepository.sendMessage(
213	      sessionId: sessionId,
214	      content: event.text,
215	    );
216	    await _consumeTurn(
217	      stream,
218	      emit,
219	      generation: generation,
220	      optimisticUserId: optimisticUser.id,
221	      optimisticAssistantId: optimisticAssistant.id,
222	    );
223	  }
224	
225	  Future<void> _onMessageRetryRequested(
226	    MessageRetryRequested event,
227	    Emitter<ChatState> emit,
228	  ) async {
229	    final current = state;
230	    if (current is! ChatReady ||
231	        current.awaitingResponse ||
232	        current.sessionId == null) {
233	      return;
234	    }
235	    final index = current.messages.indexWhere(
236	      (m) =>
237	          m.role == ChatRole.assistant &&
238	          m.status == ChatMessageStatus.failed &&
239	          _userMessageIdFor(current.messages, m) == event.userMessageId,
240	    );
241	    if (index == -1) return;
242	    if (!await _connectivityChecker.hasConnection()) return; // FR-012
243	
244	    final generation = ++_turnGeneration;
245	    final now = DateTime.now();
246	    final placeholder = ChatMessage(
247	      id: 'local-${now.microsecondsSinceEpoch}-retry',
248	      sessionId: current.sessionId!,
249	      role: ChatRole.assistant,
250	      content: '',
251	      seq: current.messages[index].seq,
252	      status: ChatMessageStatus.streaming,
253	      retryCount: current.messages[index].retryCount + 1,
254	      createdAt: now,
255	    );
256	    final updatedMessages = [...current.messages];
257	    updatedMessages[index] = placeholder;
258	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
259	
260	    final stream = _chatRepository.retryMessage(
261	      sessionId: current.sessionId!,
262	      userMessageId: event.userMessageId,
263	    );
264	    await _consumeTurn(
265	      stream,
266	      emit,
267	      generation: generation,
268	      optimisticUserId: null,
269	      optimisticAssistantId: placeholder.id,
270	    );
271	  }
272	
273	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
274	  /// and a retry.
275	  Future<void> _consumeTurn(
276	    Stream<Either<Failure, ChatStreamEvent>> stream,
277	    Emitter<ChatState> emit, {
278	    required int generation,
279	    required String? optimisticUserId,
280	    required String optimisticAssistantId,
281	  }) async {
282	    var assistantId = optimisticAssistantId;
283	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
284	      stream,
285	      onData: (result) {
286	        final latest = state;
287	        if (generation != _turnGeneration || latest is! ChatReady) {
288	          return latest;
289	        }
290	        return result.match((failure) {
291	          if (failure is AuthExpiredFailure) _reauthController.add(null);
292	          return _applyFailure(latest, assistantId, failure);
293	        }, (event) => switch (event) {
294	          MessageCreated() => () {
295	            assistantId = event.assistantMessageId;
296	            return _reconcileIds(
297	              latest,
298	              optimisticUserId,
299	              event.userMessageId,
300	              optimisticAssistantId,
301	              event.assistantMessageId,
302	            );
303	          }(),
304	          ContextReceived() => latest,
305	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
306	          StreamDone(
307	            assistantMessageId: final id,
308	            content: final c,
309	            createdAt: final t,
310	          ) =>
311	            _completeMessage(latest, id, c, t).copyWith(awaitingResponse: false),
312	        });
313	      },
314	    );
315	  }
316	
317	  void _failTurn(
318	    Emitter<ChatState> emit,
319	    String assistantId,
320	    Failure failure,
321	  ) {
322	    final latest = state;
323	    if (latest is! ChatReady) return;
324	    emit(_applyFailure(latest, assistantId, failure));
325	  }
326	
327	  /// `null` for a retry's `userMessageId` — a retry never targets an
328	  /// optimistic question, only an already-persisted one.
329	  ChatReady _reconcileIds(
330	    ChatReady current,
331	    String? optimisticUserId,
332	    String realUserId,
333	    String optimisticAssistantId,
334	    String realAssistantId,
335	  ) {
336	    final updated = [
337	      for (final m in current.messages)
338	        if (optimisticUserId != null && m.id == optimisticUserId)
339	          _withId(m, realUserId)
340	        else if (m.id == optimisticAssistantId)
341	          _withId(m, realAssistantId)
342	        else
343	          m,
344	    ];
345	    return current.copyWith(messages: updated);
346	  }
347	
348	  ChatMessage _withId(ChatMessage message, String id) => ChatMessage(
349	    id: id,
350	    sessionId: message.sessionId,
351	    role: message.role,
352	    content: message.content,
353	    seq: message.seq,
354	    status: message.status,
355	    retryCount: message.retryCount,
356	    createdAt: message.createdAt,
357	  );
358	
359	  ChatReady _appendToken(ChatReady current, String assistantId, String delta) {
360	    final updated = [
361	      for (final m in current.messages)
362	        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
363	    ];
364	    return current.copyWith(messages: updated);
365	  }
366	
367	  ChatReady _completeMessage(
368	    ChatReady current,
369	    String assistantId,
370	    String content,
371	    DateTime createdAt,
372	  ) {
373	    final updated = [
374	      for (final m in current.messages)
375	        if (m.id == assistantId)
376	          ChatMessage(
377	            id: m.id,
378	            sessionId: m.sessionId,
379	            role: m.role,
380	            content: content,
381	            seq: m.seq,
382	            status: ChatMessageStatus.complete,
383	            retryCount: m.retryCount,
384	            createdAt: createdAt,
385	          )
386	        else
387	          m,
388	    ];
389	    return current.copyWith(messages: updated);
390	  }
391	
392	  /// Keeps whatever partial `content` had already accumulated — never
393	  /// removed, hidden, or blanked (FR-005).
394	  ChatReady _applyFailure(
395	    ChatReady current,
396	    String assistantId,
397	    Failure failure,
398	  ) {
399	    final updated = [
400	      for (final m in current.messages)
401	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.failed) else m,
402	    ];
403	    return current.copyWith(messages: updated, awaitingResponse: false);
404	  }
405	
406	  ChatMessage _withContent(ChatMessage message, String content) => ChatMessage(
407	    id: message.id,
408	    sessionId: message.sessionId,
409	    role: message.role,
410	    content: content,
411	    seq: message.seq,
412	    status: message.status,
413	    retryCount: message.retryCount,
414	    createdAt: message.createdAt,
415	  );
416	
417	  ChatMessage _withStatus(ChatMessage message, ChatMessageStatus status) =>
418	      ChatMessage(
419	        id: message.id,
420	        sessionId: message.sessionId,
421	        role: message.role,
422	        content: message.content,
423	        seq: message.seq,
424	        status: status,
425	        retryCount: message.retryCount,
426	        createdAt: message.createdAt,
427	      );
428	
429	  /// Position-matching (research.md R10) — the id of the user message
430	  /// immediately preceding [message] in [messages], or `null` if it isn't
431	  /// immediately preceded by one.
432	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
433	    final index = messages.indexWhere((m) => m.id == message.id);
434	    if (index <= 0) return null;
435	    final preceding = messages[index - 1];
436	    return preceding.role == ChatRole.user ? preceding.id : null;
437	  }
438	
439	  @override
440	  Future<void> close() {
441	    unawaited(_connectivitySubscription.cancel());
442	    unawaited(_reauthController.close());
443	    return super.close();
444	  }
445	}
